-- VERIFICACION FINAL
-- ------------------------------------------------------------------
SELECT 'CATEGORIAS'      AS TABLA, COUNT(*) AS REGISTROS FROM CATEGORIAS      UNION ALL
SELECT 'BODEGAS',                  COUNT(*)               FROM BODEGAS         UNION ALL
SELECT 'METODOS_PAGO',              COUNT(*)               FROM METODOS_PAGO    UNION ALL
SELECT 'VENDEDORES',                COUNT(*)               FROM VENDEDORES      UNION ALL
SELECT 'CLIENTES',                  COUNT(*)               FROM CLIENTES        UNION ALL
SELECT 'PRODUCTOS',                 COUNT(*)               FROM PRODUCTOS       UNION ALL
SELECT 'INVENTARIO',                COUNT(*)               FROM INVENTARIO      UNION ALL
SELECT 'PEDIDOS',                   COUNT(*)               FROM PEDIDOS         UNION ALL
SELECT 'DETALLE_PEDIDOS',           COUNT(*)               FROM DETALLE_PEDIDOS UNION ALL
SELECT 'PAGOS',                     COUNT(*)               FROM PAGOS           UNION ALL
SELECT 'ENVIOS',                    COUNT(*)               FROM ENVIOS          UNION ALL
SELECT 'DEVOLUCIONES',              COUNT(*)               FROM DEVOLUCIONES
ORDER BY 1;
